const CUR={JPY:{usd:.0067,dp:0,name:'JPY'},CNY:{usd:.14,dp:2,name:'YUAN'},USD:{usd:1,dp:2,name:'USD'},EUR:{usd:1.08,dp:2,name:'EUR'},GBP:{usd:1.29,dp:2,name:'GBP'},KRW:{usd:.00073,dp:0,name:'KRW'},SGD:{usd:.75,dp:2,name:'SGD'}};
const fmt=(n,c='USD')=>Number(n||0).toLocaleString(undefined,{minimumFractionDigits:CUR[c]?.dp??2,maximumFractionDigits:CUR[c]?.dp??2});
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>new Date().toLocaleString();
const state={lang:localStorage.getItem('opo-quickpay-lang')||'zh-CN',seq:0,merchants:[],members:[],orders:[],lots:[],ledger:[],liabilities:[],auth:[]};
const t=k=>COPY[state.lang][k]??COPY['zh-CN'][k]??k;
const next=p=>`${p}-${String(++state.seq).padStart(4,'0')}`;
const merchant=id=>state.merchants.find(x=>x.id===id), member=id=>state.members.find(x=>x.id===id);
function log(event,details,amount=0,currency='USDT',merchantId='',memberId='',status='ok'){state.ledger.unshift({id:next('EV'),time:now(),event,details,amount,currency,merchantId,memberId,status})}
function init(){state.merchants.push({id:'OPO-DEMO-01',name:'OPO 演示咖啡馆',region:'日本',currency:'JPY',pointName:'JPY',wallet:'0x71C4...A09f (demo)',methods:['日本扫码支付','现金'],consumerRate:2,shareRate:1,reserveTotal:500,reserveFrozen:0,dailyIssued:0,status:'approved',isSeed:true});state.merchants.push({id:'OPO-DEMO-02',name:'OPO 演示生活馆',region:'中国',currency:'CNY',pointName:'YUAN',wallet:'0x2B38...C41e (demo)',methods:['微信支付','支付宝'],consumerRate:2,shareRate:1,reserveTotal:300,reserveFrozen:0,dailyIssued:0,status:'approved',isSeed:true});const a=addMember('林小宇',''),b=addMember('王美玲',a.id);const m=merchant('OPO-DEMO-01');const order={id:'DEMO-SALE-001',reference:'DEMO-RECEIPT-001',merchantId:m.id,memberId:b.id,amount:6800,currency:'JPY',method:'日本扫码支付',status:'pending',createdAt:now(),consumerRate:2,shareRate:1,refundable:6800,refundAmount:0,lotIds:[],frozen:0};state.orders.push(order);log(t('saleRecorded'),`${order.reference} · ¥${fmt(68,'JPY')}`,0,'JPY',m.id,b.id,'pending')}
function addMember(name,inviterId){const m={id:next('OPO-M'),name,inviterId,createdAt:now()};state.members.push(m);return m}
function approved(){return state.merchants.filter(m=>m.status==='approved')}
function fmtRate(from,to){return (CUR[from].usd/CUR[to].usd).toFixed(5)}
function pointTotals(memberId){const out={};for(const l of state.lots.filter(x=>x.memberId===memberId)){out[l.currency]=(out[l.currency]||0)+l.remaining}return out}
function statusBadge(x){const label=x==='approved'?t('approved'):x==='pending'?t('pendingReview'):x==='confirmed'?t('orderConfirmed'):x==='refund_due'?t('due'):x==='refunded'?t('refundDone'):String(x);return `<span class="status ${x==='approved'||x==='confirmed'?'good':x==='pending'||x==='refund_due'?'warn':''}">${safe(label)}</span>`}
function empty(){return `<div class="empty">${t('noData')}</div>`}
function options(rows,label,value=x=>x.id){return rows.map(x=>`<option value="${safe(value(x))}">${safe(label(x))}</option>`).join('')}
function selector(id,label,rows,labelFn,required=true){return `<label class="field">${label}<select name="${id}" ${required?'required':''}>${options(rows,labelFn)}</select></label>`}
function home(){const pending=state.orders.filter(o=>o.status==='pending').length,fr=state.merchants.reduce((a,m)=>a+m.reserveFrozen,0);return `<section class="hero"><div><p class="eyebrow">${t('homeEyebrow')}</p><h1>${t('heroTitle')}</h1><p>${t('heroBody')}</p><div class="toolbar"><button class="btn primary" data-view="apply">${t('startApply')}</button><button class="btn" data-view="member">${t('goMember')}</button></div></div><div class="hero-box"><b>${t('heroBoxTitle')}</b><ul><li>${t('heroOne')}</li><li>${t('heroTwo')}</li><li>${t('heroThree')}</li><li>${t('heroFour')}</li></ul></div></section><div class="section-head"><div><h2>${t('statsTitle')}</h2></div></div><div class="metrics"><div class="metric"><span>${t('merchantCount')}</span><strong>${approved().length}</strong></div><div class="metric"><span>${t('memberCount')}</span><strong>${state.members.length}</strong></div><div class="metric"><span>${t('pendingCount')}</span><strong>${pending}</strong></div><div class="metric"><span>${t('frozenTotal')}</span><strong>${fmt(fr)} USDT</strong></div></div><section class="panel"><h2>${t('flowTitle')}</h2><p>${t('flowBody')}</p></section><div class="cards"><article class="card"><div class="icon">🏪</div><h3>${t('whyMerchant')}</h3><p>${t('whyMerchantBody')}</p></article><article class="card"><div class="icon">🎟️</div><h3>${t('whyCustomer')}</h3><p>${t('whyCustomerBody')}</p></article><article class="card"><div class="icon">🌐</div><h3>${t('whyPlatform')}</h3><p>${t('whyPlatformBody')}</p></article></div><section class="panel"><h2>${t('fxTitle')}</h2><p>${t('fxBody')}</p><div class="callout">${t('reserveRule')}</div><div class="callout blue"><b>${t('fxLabel')}:</b> ${t('fxMock')}</div></section>`}
function methodLabel(value){for(const lang of Object.keys(COPY)){const i=COPY[lang].paymentMethods.indexOf(value);if(i>=0)return t('paymentMethods')[i]}return value}
function regionLabel(value){const i=['中国','日本','美国','其他'].indexOf(value);return i<0?value:t('regions')[i]}
function applyView(){const methods=t('paymentMethods'),curr=t('currencies'),regions=t('regions');return `<div class="section-head"><div><h2>${t('applyTitle')}</h2><p>${t('applyIntro')}</p></div></div><div class="grid-two"><section class="panel"><form id="apply-form"><div class="form-grid"><label class="field">${t('merchantName')}<input name="name" required maxlength="60" placeholder="${t('merchantNamePh')}"></label><label class="field">${t('country')}<select name="region">${regions.map((x,i)=>`<option value="${['中国','日本','美国','其他'][i]}">${x}</option>`).join('')}</select></label><label class="field">${t('currency')}<select name="currency">${['JPY','CNY','USD','EUR','GBP','KRW','SGD'].map((c,i)=>`<option value="${c}">${curr[i]}</option>`).join('')}</select></label><label class="field">${t('wallet')}<input name="wallet" required placeholder="${t('walletPh')}"></label><label class="field">${t('consumerRate')}<input name="consumerRate" type="number" min="0" max="100" step="0.01" value="2" required></label><label class="field">${t('shareRate')}<input name="shareRate" type="number" min="0" max="100" step="0.01" value="1" required></label><label class="field full">${t('reserveAmount')}<input name="reserve" type="number" min="100" step="0.01" value="100" required></label><div class="field full"><span>${t('methods')}</span><div class="method-list">${methods.map(x=>`<label class="method-option"><input type="checkbox" name="methods" value="${safe(x)}">${safe(x)}</label>`).join('')}</div></div></div><p class="small">${t('currencyHint')}</p><p class="small">${t('rateHint')}</p><p class="small">${t('reserveHint')}</p><button class="btn primary" type="submit">${t('submitApplication')}</button></form></section><section class="panel"><h2>${t('merchantList')}</h2><div class="list">${state.merchants.map(m=>`<article class="item ${m.status}"><div class="item-main"><div class="item-title">${safe(m.name)} <span class="status">${safe(m.id)}</span></div><div class="item-sub">${safe(regionLabel(m.region))} · ${safe(m.currency)} / ${safe(m.pointName)} · ${safe(m.wallet)} · ${fmt(m.reserveTotal)} USDT</div><div class="item-sub">${t('consumerReward')} ${m.consumerRate}% · ${t('shareReward')} ${m.shareRate}% · ${safe(m.methods.map(methodLabel).join(' / '))}</div></div><div class="item-actions">${statusBadge(m.status)}${m.status==='pending'?`<button class="btn small primary" data-action="approve" data-id="${safe(m.id)}">${t('approve')}</button>`:''}</div></article>`).join('')||empty()}</div></section></div>`}
function memberView(){const opts=state.members;return `<div class="section-head"><div><h2>${t('memberTitle')}</h2><p>${t('memberIntro')}</p></div></div><div class="grid-two"><section class="panel"><h3>${t('registerMember')}</h3><form id="member-form"><label class="field">${t('memberName')}<input name="name" required maxlength="40" placeholder="${t('memberNamePh')}"></label>${selector('inviter',t('inviter'),opts,m=>`${m.id} · ${m.name}`,false).replace('<select','<select')}<button class="btn primary">${t('registerMember')}</button></form><h3>${t('memberList')}</h3><div class="list">${opts.map(m=>{const totals=pointTotals(m.id),summary=Object.entries(totals).map(([c,n])=>`${fmt(n,c)} ${CUR[c].name}`).join(' · ')||'—';return `<article class="item"><div class="item-main"><div class="item-title">${safe(m.id)} · ${safe(m.name)}</div><div class="item-sub">${t('inviter')}: ${safe(m.inviterId||t('noInviter'))}</div><div class="item-sub">${t('pointsByCurrency')}: <b>${safe(summary)}</b></div><div class="item-sub">${t('walletAsset')}: ${fmt((totals.USDT||0))} USDT · ${t('available')}</div></div></article>`}).join('')||empty()}</div></section><section class="panel"><h3>${t('delegateTitle')}</h3><p>${t('delegateIntro')}</p><form id="auth-form">${selector('memberId',t('delegateMember'),opts,m=>`${m.id} · ${m.name}`)}${selector('merchantId',t('delegateMerchant'),state.merchants,m=>`${m.name} (${m.currency})`)}<label class="check"><input type="checkbox" name="enabled">${t('grant')}</label><button class="btn primary">${t('grant')} / ${t('revoke')}</button></form><h3>${t('delegateTitle')}</h3><div class="list">${state.auth.map(a=>`<div class="item"><div class="item-main"><b>${safe(member(a.memberId)?.name||a.memberId)}</b><div class="item-sub">${safe(merchant(a.merchantId)?.name||a.merchantId)}</div></div>${statusBadge(a.enabled?'approved':'pending')}</div>`).join('')||empty()}</div><div class="callout blue">${t('walletAsset')} · BSC / USDT · ${t('demoWarning')}</div></section></div>`}
function cashierView(){const members=state.members,merchants=approved();return `<div class="section-head"><div><h2>${t('cashierTitle')}</h2><p>${t('cashierIntro')}</p></div></div><div class="grid-two"><section class="panel"><form id="sale-form">${selector('merchantId',t('selectMerchant'),merchants,m=>`${m.name} · ${m.currency} · ${fmt(m.reserveTotal-m.reserveFrozen)} USDT ${t('available')}`)}${selector('memberId',t('selectMember'),members,m=>`${m.id} · ${m.name}`)}<label class="field">${t('billAmount')}<input name="amount" type="number" min="0.01" step="0.01" value="100" required></label><label class="field">${t('method')}<select name="method" id="sale-method"></select></label><label class="field">${t('reference')}<input name="reference" value="SALE-${Date.now().toString().slice(-7)}" required></label><label class="check"><input name="received" type="checkbox" required>${t('receivedCheck')}</label><button class="btn primary">${t('recordSale')}</button></form></section><section class="panel"><h3>${t('pendingOrders')}</h3><div class="list">${state.orders.filter(o=>o.status==='pending').map(o=>{const m=merchant(o.merchantId),mem=member(o.memberId),auth=state.auth.some(a=>a.memberId===o.memberId&&a.merchantId===o.merchantId&&a.enabled);return `<article class="item pending"><div class="item-main"><div class="item-title">${safe(o.reference)} · ${fmt(o.amount,o.currency)} ${safe(o.currency)}</div><div class="item-sub">${safe(mem?.id)} · ${safe(mem?.name)} → ${safe(m?.name)}</div><div class="item-sub">${safe(methodLabel(o.method))} · ${t('orderPending')}</div></div><div class="item-actions"><button class="btn small primary" data-action="confirm-customer" data-id="${safe(o.id)}">${t('confirmCustomer')}</button><button class="btn small" data-action="confirm-merchant" data-id="${safe(o.id)}" ${auth?'':'disabled'} title="${auth?'':t('errAuth')}">${t('confirmDelegate')}</button></div></article>`}).join('')||empty()}</div></section></div><section class="panel"><h3>${t('recordsTitle')}</h3>${ordersTable()}</section>`}
function ordersTable(){if(!state.orders.length)return empty();return `<div class="table-wrap"><table><thead><tr>${['colOrder','colMember','colMerchant','colAmount','colStatus','colDetails'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${state.orders.map(o=>{const m=merchant(o.merchantId),mem=member(o.memberId);return `<tr><td>${safe(o.reference)}</td><td>${safe(mem?.id||'')}</td><td>${safe(m?.name||'')}</td><td>${fmt(o.amount,o.currency)} ${o.currency}</td><td>${statusBadge(o.status)}</td><td>${o.operator?safe(t('operator')+': '+o.operator):''}${o.refundAmount?` · ${t('refund')}: ${fmt(o.refundAmount,o.currency)}`:''}${o.frozen?` · ${t('locked')}: ${fmt(o.frozen)} USDT`:''}${o.status==='confirmed'?` <button class="btn small" data-action="refund-view" data-id="${safe(o.id)}">${t('refundAction')}</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`}
function pointsView(){const members=state.members,merchants=approved();return `<div class="section-head"><div><h2>${t('pointsTitle')}</h2><p>${t('pointsIntro')}</p></div></div><section class="panel"><h3>${t('redeemTitle')}</h3><form id="redeem-form" class="form-grid">${selector('merchantId',t('redeemMerchant'),merchants,m=>`${m.name} · ${m.currency}`)}${selector('memberId',t('redeemMember'),members,m=>`${m.id} · ${m.name}`)}<label class="field">${t('redeemAmount')}<input name="amount" type="number" min="0.01" step="0.01" value="10" required></label><label class="field">${t('redeemCurrency')}<select name="currency">${['JPY','CNY','USD','EUR','GBP','KRW','SGD'].map(c=>`<option value="${c}">${c} · ${CUR[c].name}</option>`).join('')}</select></label><div class="field full"><button class="btn primary">${t('redeemButton')}</button></div></form><p class="small">${t('converted')} · ${t('fxMock')}</p></section><section class="panel"><h3>${t('pointLedger')}</h3>${lotsTable()}</section><section class="panel"><h3>${t('refundTitle')}</h3><div class="list">${state.orders.filter(o=>o.status==='confirmed'&&o.refundable>0).map(o=>`<article class="item"><div class="item-main"><b>${safe(o.reference)}</b><div class="item-sub">${fmt(o.refundable,o.currency)} ${o.currency} · ${safe(member(o.memberId)?.name||'')}</div><div class="item-sub">${o.recoveryDue?`<span class="status warn">${t('due')}: ${fmt(o.recoveryDue)} USDT</span>`:''}</div></div><form class="refund-form item-actions" data-id="${safe(o.id)}"><input name="amount" aria-label="${t('refundPartial')}" type="number" min="0.01" max="${o.refundable}" step="0.01" placeholder="${t('refundPartial')}" required><button class="btn small danger">${t('refundDone')}</button></form></article>`).join('')||empty()}</div><p class="small">${t('refundDue')}</p></section>`}
function lotsTable(){if(!state.lots.length)return empty();return `<div class="table-wrap"><table><thead><tr>${['colMember','pointCurrency','earnedFrom','colCurrency','issued','remaining','colStatus'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${state.lots.map(l=>`<tr><td>${safe(member(l.memberId)?.id||'')}</td><td>${safe(CUR[l.currency].name)}</td><td>${safe(merchant(l.issuer)?.name||'')}</td><td>${safe(l.currency)}</td><td>${fmt(l.original,l.currency)}</td><td>${fmt(l.remaining,l.currency)}</td><td>${safe(l.kind)}</td></tr>`).join('')}</tbody></table></div>`}
function reserveView(){const m=merchant(document.querySelector('[name="reserveSelect"]')?.value)||approved()[0];if(!m)return empty();const available=m.reserveTotal-m.reserveFrozen,target=m.dailyIssued*1.5,pct=target?Math.min(100,m.reserveTotal/target*100):100;return `<div class="section-head"><div><h2>${t('reserveTitle')}</h2><p>${t('reserveIntro')}</p></div></div><section class="panel"><div class="toolbar">${selector('reserveSelect',t('selectReserveMerchant'),approved(),x=>`${x.name} · ${x.currency}`).replace('name="reserveSelect"','name="reserveSelect" data-reserve-select')}</div><div class="callout blue"><b>${t('walletAddress')}:</b> ${safe(m.wallet)}<br>${t('fxLabel')}: ${t('fxMock')}</div><div class="metrics"><div class="metric"><span>${t('totalReserve')}</span><strong>${fmt(m.reserveTotal)} USDT</strong></div><div class="metric"><span>${t('frozenReserve')}</span><strong>${fmt(m.reserveFrozen)} USDT</strong></div><div class="metric"><span>${t('availableReserve')}</span><strong>${fmt(available)} USDT</strong></div></div><div class="grid-two"><div><div class="balance-row"><span>${t('dailyIssue')}</span><b>${fmt(m.dailyIssued)} USDT</b></div><div class="balance-row"><span>${t('targetReserve')}</span><b>${fmt(target)} USDT</b></div><div class="progress"><i style="width:${pct}%"></i></div></div><form id="topup-form"><input type="hidden" name="merchantId" value="${safe(m.id)}"><h3>${t('topUpTitle')}</h3><label class="field">${t('topUpAmount')}<input name="amount" type="number" min="0.01" step="0.01" value="100" required></label><button class="btn primary">${t('topUpButton')}</button></form></div></section><section class="panel"><h3>${t('exitTitle')}</h3><p>${t('exitBody')}</p><button class="btn" data-action="exit" data-id="${safe(m.id)}">${t('exitButton')}</button></section>`}
function recordsView(){return `<div class="section-head"><div><h2>${t('recordsTitle')}</h2><p>${t('recordsIntro')}</p></div></div><section class="panel"><h3>${t('ordersTable')}</h3>${ordersTable()}</section><section class="panel"><h3>${t('ledgerTable')}</h3>${state.ledger.length?`<div class="table-wrap"><table><thead><tr>${['colTime','colEvent','colMerchant','colMember','colAmount','colStatus','colDetails'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${state.ledger.map(x=>`<tr><td>${safe(x.time)}</td><td>${safe(x.event)}</td><td>${safe(merchant(x.merchantId)?.name||'—')}</td><td>${safe(member(x.memberId)?.id||'—')}</td><td>${fmt(x.amount,x.currency)} ${safe(x.currency)}</td><td>${statusBadge(x.status)}</td><td>${safe(x.details)}</td></tr>`).join('')}</tbody></table></div>`:empty()}</section><section class="panel"><h3>${t('responsibility')}</h3>${state.liabilities.length?`<div class="table-wrap"><table><thead><tr><th>${t('colSource')}</th><th>${t('colTarget')}</th><th>${t('colMember')}</th><th>${t('colAmount')}</th><th>${t('colStatus')}</th></tr></thead><tbody>${state.liabilities.map(x=>`<tr><td>${safe(merchant(x.issuer)?.name||'')}</td><td>${safe(merchant(x.redeemer)?.name||'')}</td><td>${safe(member(x.memberId)?.id||'')}</td><td>${fmt(x.amount,x.currency)} ${safe(x.currency)}</td><td>${t('settled')}</td></tr>`).join('')}</tbody></table></div>`:empty()}</section>`}
const VIEWS={home,apply:applyView,member:memberView,cashier:cashierView,points:pointsView,reserve:reserveView,records:recordsView};let current='home';
function render(){document.documentElement.lang=state.lang;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.querySelector('#language').value=state.lang;document.querySelector('#nav').innerHTML=Object.entries({home:'home',apply:'apply',member:'member',cashier:'cashier',points:'points',reserve:'reserve',records:'records'}).map(([id,key])=>`<button type="button" data-view="${id}" aria-current="${current===id}">${t(key)}</button>`).join('');document.querySelector('#app').innerHTML=(VIEWS[current]||home)();bindDynamic()}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4200)}
function go(id){current=id;render();window.scrollTo({top:0,behavior:'smooth'})}
function bindDynamic(){const methodSelect=document.querySelector('#sale-method'),merchantSelect=document.querySelector('#sale-form [name="merchantId"]');if(methodSelect&&merchantSelect){const fill=()=>{const m=merchant(merchantSelect.value);methodSelect.innerHTML=(m?.methods||[]).map(x=>`<option>${safe(x)}</option>`).join('')};merchantSelect.addEventListener('change',fill);fill()}}
function submitApplication(f){const d=new FormData(f),name=String(d.get('name')||'').trim(),wallet=String(d.get('wallet')||'').trim(),reserve=Number(d.get('reserve')),consumerRate=Number(d.get('consumerRate')),shareRate=Number(d.get('shareRate')),methods=d.getAll('methods');if(!name)throw Error(t('errName'));if(!wallet)throw Error(t('errWallet'));if(!Number.isFinite(reserve)||reserve<100)throw Error(t('errReserve'));if(consumerRate<0||shareRate<0||consumerRate+shareRate>100)throw Error(t('errRates'));if(!methods.length)throw Error(t('errMethods'));const currency=d.get('currency'),m={id:next('OPO-MER'),name,region:d.get('region'),currency,pointName:CUR[currency].name,wallet,methods,consumerRate,shareRate,reserveTotal:reserve,reserveFrozen:0,dailyIssued:0,status:'pending',isSeed:false};state.merchants.push(m);log(t('toastApplied'),`${m.name} · ${currency} · ${m.wallet}`,reserve,'USDT',m.id);return m}
function recordSale(f){const d=new FormData(f),m=merchant(d.get('merchantId')),mem=member(d.get('memberId')),amount=Number(d.get('amount')),reference=String(d.get('reference')||'').trim();if(!m||m.status!=='approved'||m.reserveTotal<=m.reserveFrozen)throw Error(t('errMerchant'));if(!mem)throw Error(t('errMember'));if(!Number.isFinite(amount)||amount<=0)throw Error(t('errAmount'));if(!reference||state.orders.some(o=>o.reference===reference))throw Error(t('errReference'));if(!d.has('received'))throw Error(t('errReceived'));const o={id:next('ORD'),reference,merchantId:m.id,memberId:mem.id,amount,currency:m.currency,method:d.get('method'),status:'pending',createdAt:now(),consumerRate:m.consumerRate,shareRate:m.shareRate,refundable:amount,refundAmount:0,lotIds:[],frozen:0};state.orders.unshift(o);log(t('saleRecorded'),`${reference} · ${fmt(amount,m.currency)} ${m.currency} · ${o.method}`,amount,m.currency,m.id,mem.id,'pending');return o}
function isAuthorized(memId,merchantId){return state.auth.some(x=>x.memberId===memId&&x.merchantId===merchantId&&x.enabled)}
function confirmSale(orderId,actor){const o=state.orders.find(x=>x.id===orderId&&x.status==='pending');if(!o)throw Error(t('errPending'));const m=merchant(o.merchantId),mem=member(o.memberId);if(actor==='merchant'&&!isAuthorized(mem.id,m.id))throw Error(t('errAuth'));const consumer=o.amount*o.consumerRate/100,share=mem.inviterId?o.amount*o.shareRate/100:0,usd=(consumer+share)*CUR[o.currency].usd;if(usd>m.reserveTotal-m.reserveFrozen+1e-8)throw Error(t('errFunds'));o.status='confirmed';o.operator=actor==='merchant'?t('merchantActor'):t('customer');o.consumerPoints=consumer;o.sharePoints=share;o.frozen=usd;m.reserveFrozen+=usd;m.dailyIssued+=usd;const addLot=(recipient,amount,kind)=>{if(!recipient||amount<=0)return;const lot={id:next('LOT'),orderId:o.id,memberId:recipient,issuer:m.id,currency:o.currency,original:amount,remaining:amount,kind};state.lots.push(lot);o.lotIds.push(lot.id)};addLot(mem.id,consumer,t('consumerReward'));addLot(mem.inviterId,share,t('shareReward'));log(t('toastConfirmed'),`${o.reference} · ${fmt(consumer,o.currency)} ${m.pointName} + ${fmt(share,o.currency)} · ${fmt(usd)} USDT`,usd,'USDT',m.id,mem.id,'ok');return o}
function updateAuthorization(f){const d=new FormData(f),enabled=d.has('enabled'),key={memberId:d.get('memberId'),merchantId:d.get('merchantId')};let a=state.auth.find(x=>x.memberId===key.memberId&&x.merchantId===key.merchantId);if(a)a.enabled=enabled;else state.auth.push({...key,enabled});log(t('toastDelegate'),`${member(key.memberId)?.name} → ${merchant(key.merchantId)?.name}: ${enabled?t('delegated'):t('notDelegated')}`,0,'USDT',key.merchantId,key.memberId);}
function redeem(f){const d=new FormData(f),m=merchant(d.get('merchantId')),mem=member(d.get('memberId')),toCurrency=d.get('currency'),amount=Number(d.get('amount'));if(!m||!mem)throw Error(t('errMember'));if(!Number.isFinite(amount)||amount<=0)throw Error(t('errAmount'));const targetUsd=amount*CUR[toCurrency].usd;const candidates=state.lots.filter(l=>l.memberId===mem.id&&l.remaining>0).sort((a,b)=>state.lots.indexOf(a)-state.lots.indexOf(b));const totalUsd=candidates.reduce((n,l)=>n+l.remaining*CUR[l.currency].usd,0);if(totalUsd+1e-8<targetUsd)throw Error(t('errPoints'));let leftUsd=targetUsd,allocations=[];for(const l of candidates){if(leftUsd<=1e-8)break;const take=Math.min(l.remaining,leftUsd/CUR[l.currency].usd);l.remaining-=take;const usd=take*CUR[l.currency].usd;leftUsd-=usd;allocations.push({lot:l,points:take,usd});if(l.issuer!==m.id)state.liabilities.push({issuer:l.issuer,redeemer:m.id,memberId:mem.id,amount:usd/CUR[toCurrency].usd,currency:toCurrency,status:'recorded'})}log(t('used'),`${fmt(amount,toCurrency)} ${toCurrency} · ${allocations.map(a=>`${fmt(a.points,a.lot.currency)} ${a.lot.currency} (${fmt(a.points*CUR[a.lot.currency].usd)} USDT)`).join(' + ')}`,amount,toCurrency,m.id,mem.id,'ok');}
function refund(orderId,amount){const o=state.orders.find(x=>x.id===orderId);if(!o||o.status!=='confirmed')throw Error(t('errPending'));if(!Number.isFinite(amount)||amount<=0||amount>o.refundable+1e-8)throw Error(t('errRefund'));const proportion=amount/(o.amount||1);let release=0,due=0;for(const lotId of o.lotIds){const lot=state.lots.find(x=>x.id===lotId);if(!lot)continue;const reversal=lot.original*proportion,available=Math.min(reversal,lot.remaining);lot.remaining-=available;const recovered=available*CUR[lot.currency].usd;release+=recovered;due+=Math.max(0,(reversal-available)*CUR[lot.currency].usd)}const m=merchant(o.merchantId),toRelease=Math.min(m.reserveFrozen,release);m.reserveFrozen-=toRelease;o.frozen=Math.max(0,o.frozen-toRelease);o.refundable-=amount;o.refundAmount+=amount;if(due>0)o.recoveryDue=(o.recoveryDue||0)+due;if(o.refundable<=1e-8)o.status='refunded';log(t('refund'),`${o.reference} · ${fmt(amount,o.currency)} ${o.currency} · ${t('unlocked')} ${fmt(toRelease)} USDT${due?` · ${t('due')} ${fmt(due)} USDT`:''}`,amount,o.currency,m.id,o.memberId,due?'refund_due':'ok');}
function doAction(button){const id=button.dataset.id;switch(button.dataset.action){case'approve':{const m=merchant(id);if(m){m.status='approved';log(t('toastApproved'),m.name,0,'USDT',m.id);toast(t('toastApproved'))}break}case'confirm-customer':confirmSale(id,'customer');toast(t('toastConfirmed'));break;case'confirm-merchant':confirmSale(id,'merchant');toast(t('toastConfirmed'));break;case'exit':{const m=merchant(id);log(t('exit'),`${m.name} · ${t('availableReserve')} ${fmt(m.reserveTotal-m.reserveFrozen)} USDT · ${t('due')}`,m.reserveTotal-m.reserveFrozen,'USDT',m.id,'','pending');toast(t('toastExit'));break}case'refund-view':go('points');break}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return}const b=e.target.closest('[data-action]');if(b){try{doAction(b);render()}catch(err){toast(err.message)}}});
document.querySelector('#language').addEventListener('change',e=>{state.lang=e.target.value;localStorage.setItem('opo-quickpay-lang',state.lang);render();toast(t('toastLanguage'))});
document.querySelector('#app').addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();try{if(f.matches('.refund-form')){refund(f.dataset.id,Number(new FormData(f).get('amount')));toast(t('toastRefund'));render();return}switch(f.id){case'apply-form':submitApplication(f);toast(t('toastApplied'));break;case'member-form':{const d=new FormData(f),m=addMember(String(d.get('name')||'').trim(),d.get('inviter')||'');if(!m.name)throw Error(t('errName'));log(t('toastMember')+m.id,m.name,0,'USDT','',m.id);toast(t('toastMember')+m.id);break}case'auth-form':updateAuthorization(f);toast(t('toastDelegate'));break;case'sale-form':recordSale(f);toast(t('toastSale'));break;case'redeem-form':redeem(f);toast(t('toastRedeem'));break;case'topup-form':{const d=new FormData(f),m=merchant(d.get('merchantId')),n=Number(d.get('amount'));if(!Number.isFinite(n)||n<=0)throw Error(t('errTopup'));m.reserveTotal+=n;log(t('topup'),m.name,n,'USDT',m.id);toast(t('toastTopup'));break}}render()}catch(err){toast(err.message)}});
init();render();
